p=argparse.ArgumentParser();p.add_argument('root',type=Path);p.add_argument('--output',type=Path,required=True);a=p.parse_args();w=Path(__file__).parent;project=Path('/Users/cam/DEV/fvwm3/builddir/codex-2026-10-13/github-setup/publish');source=json.loads((w/'source01.json').read_text());sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest();root=a.root.resolve(strict=True)
