for n in ['baseline','candidate','native-timeout']:
 f=root/n;assert f.is_file() and not f.is_symlink();h=sha(f);assert h==read(n+'-before.sha256',128).decode().strip()==read(n+'-after.sha256',128).decode().strip();assert f.stat().st_size==int(read(n+'.bytes',32).decode());
 if n!='native-timeout':manifest['artifacts'][n]={'sha256':h,'bytes':f.stat().st_size}
for label in ['baseline-probe','cjson','candidate-probe','yyjson','baseline','candidate','native-timeout']:assert read('compile-'+label+'.exit',16).strip()==b'0'
