 prefix='captures/run-'+str(i);backend=read(prefix+'.backend',32).decode().strip();assert backend in ['baseline','candidate'];args=read(prefix+'.args',1024).decode('ascii').splitlines();assert 0<len(args)<=12 and all(0<len(x)<=64 for x in args);raw=read(prefix+'.exit',16).decode().strip();assert re.fullmatch(r'[0-9]{1,3}',raw);row={'backend':backend,'args':args,'exit':int(raw)}
