  n=prefix+'.'+kind;raw=read(n,limit);row[kind]={'path':n,'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
 for suffix in ['backend','args','exit','stdout','stderr','metrics']:expected_names.add(prefix+'.'+suffix)
 manifest['runs'].append(row)
